  private def stripPunct(word: String): String = {
    val leadingStripped = word.dropWhile(punctuation.contains)
    leadingStripped.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripPunct(word) else word
    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) return None

    val truncated = maxLength match {
      case Some(max) if normalized.length > max => normalized.take(max)
      case _ => normalized
    }

    if (truncated.isEmpty) None else Some(truncated)
  }

  def tokenize(text: String): List[Token] = {
    val words = if (text.trim.isEmpty) Array.empty[String] else text.split("\\s+")
    val tokens = ListBuffer.empty[Token]

    words.zipWithIndex.foreach { case (word, idx) =>
      processToken(word).foreach { processed =>
        tokens += Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }

    tokens.toList
  }

